import sys
import collections
import dataclasses


@dataclasses.dataclass
class BW:
    black: int
    white: int


def go(v, g, cnt, cols):
    for togo in g[v]:
        go(togo, g, cnt, cols)
        cnt[v].black += cnt[togo].black
        cnt[v].white += cnt[togo].white
    cnt[v].black += cols[v] == 'B'
    cnt[v].white += cols[v] == 'W'


def main():
    n = int(input())
    g = collections.defaultdict(list)
    q = [int(x) for x in input().split()]
    for i in range(1, n):
        g[q[i - 1]].append(i + 1)
    cnt = {(i + 1): BW(0, 0) for i in range(n)}
    colors = {(i + 1): c for i, c in enumerate(input())}
    go(1, g, cnt, colors)
    ans = 0
    for val in cnt.values():
        if val.black == val.white:
            ans += 1
    print(ans)


t = int(input())
for _ in range(t):
    main()

