def inp_arr():
    return list(map(int, input().strip().split(' ')))


def inp_str_arr():
    return list(input().strip().split(' '))


def inp_str():
    return input()


def cal_2s(n):
    cnt = 0
    while n % 2 == 0:
        cnt += 1
        n = n // 2
    return cnt


def solve():
    n, = inp_arr()
    a = inp_arr()
    cnt = 0
    for x in a:
        cnt += cal_2s(x)
    if cnt >= n:
        print(0)
        return
    lis = []
    for i in range(1, n + 1):
        lis.append(cal_2s(i))
    lis.sort(reverse=True)
    need = n - cnt
    ans = 0
    i = 0
    while need > 0 and i < n:
        ans += 1
        need = need - lis[i]
        i += 1
    if need > 0:
        print(-1)
        return
    print(ans)


tt, = inp_arr()
for t in range(tt):
    solve()

