def eraseLex(alpha, limit, div):
    lst = []
    letAns = 'a'
    for let in alpha.keys():
        if alpha[let] == 0 or div == 0:
            letAns = let
            break
        else:
            lst.append(let)
            div -= 1
    theMin = min([alpha[i] for i in lst], default=limit)
    if theMin > limit:
        theMin = limit
    for i in lst:
        alpha[i] -= theMin
    return theMin * letAns


def func2():
    n, k = map(int, input().split())
