def isSorted(n, arr):
    k = 0
    for a in range(n):
        if arr[a] < 0:
            k += 1
    for i in range(n):
        if i < k:
            if not arr[i] < 0:
                arr[i] = -arr[i]
        elif i >= k:
            if arr[i] < 0:
                arr[i] = -arr[i]
    for i in range(n):
        if i < k and i + 1 < k and arr[i] > arr[i + 1]:
            return 'NO'
        elif i >= k and i + 1 < n and arr[i] > arr[i + 1]:
            return 'NO'
    return 'YES'


