a = []
n, m = 0, 0


def bis(lef, rig):
    if rig - lef == 1:
        return rig
    time = [0] * n
    mid = lef + (rig - lef) // 2
    surp = 0
    for i in a:
        if time[i - 1] < mid:
            time[i - 1] += 1
        else:
            surp += 1
    for i in time:
        surp -= (mid - i) // 2
    if surp <= 0:
        return bis(lef, mid)
    else:
        return bis(mid, rig)


