    return int(input())


def input_list():
    return list(map(int, input().split()))


def input_string():
    s = input()
    return list(s[:len(s) - 1])


def input_space_seperated_integer_variables():
    return map(int, input().split())


def number_of_candies_to_be_eaten(candy_boxes: List[int], number_of_boxes: int
    ) ->int:
    candies_to_be_eaten = 0
    candy_boxes.sort()
    smallest_candy_box = candy_boxes[0]
    for i in range(1, number_of_boxes):
        candies_to_be_eaten += candy_boxes[i] - smallest_candy_box
    return candies_to_be_eaten


